/*
 * Krakatoa — the generic foods.
 *
 * An egg, a tablespoon of butter, a cup of rice: everything you would type
 * rather than scan, and the thing a barcode tracker is worst at. 150 foods with
 * USDA's own household portions, generated by `scripts/basics.build.mjs`.
 *
 * Fetched ONCE and kept, because this is content and not state: it changes when
 * the build script re-runs, never while he is using the app. Searching it is
 * therefore local, instant and offline — which is why basics can be shown while
 * the network results for the same query are still in flight.
 */

import { useEffect, useState } from 'react'

let cache = null
let inFlight = null

export async function loadBasics() {
  if (cache) return cache
  if (inFlight) return inFlight
  inFlight = fetch('/api/basics')
    .then(r => r.json())
    .then(d => {
      cache = { categories: d.categories || [], foods: (d.foods || []).map(toFood) }
      return cache
    })
    .catch(() => ({ categories: [], foods: [] }))
    .finally(() => { inFlight = null })
  return inFlight
}

/** Catalog row -> the same food shape a scan or a search produces. */
const toFood = (f) => ({
  id: f.id,
  name: f.name,
  brand: null,
  gtin: null,
  image: null,
  source: 'basic',
  category: f.category,
  fdcId: f.fdcId,
  usdaName: f.usdaName,
  portions: f.portions,
})

export function useBasics() {
  const [state, setState] = useState(cache || { categories: [], foods: [] })
  useEffect(() => {
    let alive = true
    loadBasics().then(d => { if (alive) setState(d) })
    return () => { alive = false }
  }, [])
  return state
}

/**
 * Rank matches the way the lift catalog in Bushido does, and for the same reason:
 * a list of 150 in an OS picker is a wheel you cannot aim with one thumb.
 *
 *   name prefix  >  word prefix  >  substring  >  the USDA description
 *
 * Every word of a multi-word query has to match SOMETHING, so "peanut butter"
 * cannot return every butter — the failure that makes a search feel broken.
 */
export function searchBasics(foods, query, limit = 25) {
  const q = String(query || '').trim().toLowerCase()
  if (!q) return []
  const words = q.split(/\s+/).filter(Boolean)

  const scored = []
  for (const food of foods) {
    const name = food.name.toLowerCase()
    const usda = String(food.usdaName || '').toLowerCase()
    const cat = String(food.category || '').toLowerCase()

    let score = 0
    let ok = true
    for (const w of words) {
      if (name.startsWith(w)) score += 100
      else if (name.split(/[\s,]+/).some(part => part.startsWith(w))) score += 60
      else if (name.includes(w)) score += 30
      else if (cat.includes(w)) score += 12
      else if (usda.includes(w)) score += 8
      else { ok = false; break }
    }
    if (!ok) continue
    // A shorter name matching the same words is the more generic food, and the
    // generic one is what "egg" should return.
    score -= name.length / 20
    scored.push({ food, score })
  }

  return scored.sort((a, b) => b.score - a.score).slice(0, limit).map(s => s.food)
}

/** The catalog grouped for browsing, in the order the build script declared. */
export function byCategory({ categories, foods }) {
  return categories
    .map(c => ({ category: c, foods: foods.filter(f => f.category === c) }))
    .filter(g => g.foods.length)
}
